package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct { // 01 ORDER-REC, 15 bytes
	OrId    string          // PIC X(5) @0 len=5
	OrStat  string          // PIC X(1) @5 len=1
	OrQty   int64           // PIC 9(3) @6 len=3
	OrPrice decimal.Decimal // PIC 9(4)V99 @9 len=6
}

// Standalone working-storage items
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsTotal decimal.Decimal // PIC 9(8)V99
var WsGrand decimal.Decimal // PIC 9(10)V99
var WsNewCount int64
var WsShipCount int64
var WsCancelCount int64
var WsInvalid int64
var WsBadQty int64
var WsQtyEd string   // PIC ZZ9 len=3
var WsPriceEd string // PIC Z,ZZ9.99 len=8
var WsTotalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13
var WsGrandEd string // PIC Z,ZZZ,ZZZ,ZZ9.99 len=16

var OrdRec OrderRec

var orderLines []string
var orderIdx int

func editInteger(pic string, digits string) string {
	out := make([]byte, 0, len(pic))
	suppressed := true
	di := 0
	for i := 0; i < len(pic); i++ {
		c := pic[i]
		if c == 'Z' || c == '9' {
			d := digits[di]
			di++
			if c == '9' {
				out = append(out, d)
				suppressed = false
			} else {
				if suppressed && d == '0' {
					out = append(out, ' ')
				} else {
					out = append(out, d)
					suppressed = false
				}
			}
		} else if c == ',' {
			if suppressed {
				out = append(out, ' ')
			} else {
				out = append(out, ',')
			}
		} else {
			out = append(out, c)
		}
	}
	return string(out)
}

func fmt99(v int64) string {
	m := v % 100
	if m < 0 {
		m = -m
		m = m % 100
	}
	return fmt.Sprintf("%02d", m)
}

func fmtQtyEd(q int64) string {
	m := q % 1000
	if m < 0 {
		m = -m
	}
	s := fmt.Sprintf("%03d", m)
	return editInteger("ZZ9", s)
}

func fmtPriceEd(p decimal.Decimal) string {
	cents := p.Shift(2).Truncate(0).IntPart()
	if cents < 0 {
		cents = -cents
	}
	cents = cents % 1000000
	intPart := cents / 100
	frac := cents % 100
	intStr := fmt.Sprintf("%04d", intPart)
	intFmt := editInteger("Z,ZZ9", intStr)
	return intFmt + "." + fmt.Sprintf("%02d", frac)
}

func fmtTotalEd(t decimal.Decimal) string {
	cents := t.Shift(2).Truncate(0).IntPart()
	if cents < 0 {
		cents = -cents
	}
	cents = cents % 10000000000
	intPart := cents / 100
	frac := cents % 100
	intStr := fmt.Sprintf("%08d", intPart)
	intFmt := editInteger("ZZ,ZZZ,ZZ9", intStr)
	return intFmt + "." + fmt.Sprintf("%02d", frac)
}

func fmtGrandEd(g decimal.Decimal) string {
	cents := g.Shift(2).Truncate(0).IntPart()
	if cents < 0 {
		cents = -cents
	}
	cents = cents % 1000000000000
	intPart := cents / 100
	frac := cents % 100
	intStr := fmt.Sprintf("%010d", intPart)
	intFmt := editInteger("Z,ZZZ,ZZZ,ZZ9", intStr)
	return intFmt + "." + fmt.Sprintf("%02d", frac)
}

func storeTotal(v decimal.Decimal) decimal.Decimal {
	scaled := v.Shift(2).Truncate(0)
	mod := decimal.New(1, 10)
	var r decimal.Decimal
	if scaled.IsNegative() {
		r = scaled.Neg().Mod(mod).Neg()
		if r.IsZero() {
			r = decimal.Zero
		}
	} else {
		r = scaled.Mod(mod)
	}
	return r.Shift(-2)
}

func storeGrand(v decimal.Decimal) decimal.Decimal {
	scaled := v.Shift(2).Truncate(0)
	mod := decimal.New(1, 12)
	var r decimal.Decimal
	if scaled.IsNegative() {
		r = scaled.Neg().Mod(mod).Neg()
		if r.IsZero() {
			r = decimal.Zero
		}
	} else {
		r = scaled.Mod(mod)
	}
	return r.Shift(-2)
}

func parseQty(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	n, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		return 0
	}
	return n
}

func parsePrice(s string) decimal.Decimal {
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.Zero
	}
	n, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		d, err2 := decimal.NewFromString(t)
		if err2 != nil {
			return decimal.Zero
		}
		return d.Truncate(2)
	}
	return decimal.New(n, -2)
}

func MAINPARA() {
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			orderLines = nil
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	} else {
		scanner := bufio.NewScanner(f)
		scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
		for scanner.Scan() {
			orderLines = append(orderLines, scanner.Text())
		}
		if serr := scanner.Err(); serr != nil {
			fmt.Fprintln(os.Stderr, serr)
			os.Exit(1)
		}
		f.Close()
	}
	READPARA()
	for WsEofFlag != "Y" {
		PROCESSPARA()
	}
	SUMMARYPARA()
}

func READPARA() {
	if orderIdx < len(orderLines) {
		line := orderLines[orderIdx]
		orderIdx++
		if len(line) < 15 {
			line += strings.Repeat(" ", 15-len(line))
		} else if len(line) > 15 {
			line = line[:15]
		}
		OrdRec.OrId = line[0:5]
		OrdRec.OrStat = line[5:6]
		OrdRec.OrQty = parseQty(line[6:9])
		OrdRec.OrPrice = parsePrice(line[9:15])
	} else {
		WsEofFlag = "Y"
	}
}

func PROCESSPARA() {
	WsTotal = decimal.Zero
	if OrdRec.OrQty == 0 {
		WsBadQty = (WsBadQty + 1) % 100
		fmt.Printf("%s BAD QTY\n", OrdRec.OrId)
	} else if OrdRec.OrStat == "N" {
		raw := decimal.NewFromInt(OrdRec.OrQty).Mul(OrdRec.OrPrice)
		truncated := raw.Truncate(2)
		WsTotal = storeTotal(truncated)
		WsNewCount = (WsNewCount + 1) % 100
		SHOWPARA()
	} else if OrdRec.OrStat == "S" {
		raw := decimal.NewFromInt(OrdRec.OrQty).Mul(OrdRec.OrPrice).Mul(decimal.New(105, -2))
		rounded := raw.Round(2)
		WsTotal = storeTotal(rounded)
		WsShipCount = (WsShipCount + 1) % 100
		SHOWPARA()
	} else if OrdRec.OrStat == "C" {
		WsCancelCount = (WsCancelCount + 1) % 100
		SHOWPARA()
	} else {
		WsInvalid = (WsInvalid + 1) % 100
		fmt.Printf("%s BAD STATUS %s\n", OrdRec.OrId, OrdRec.OrStat)
	}
	rawGrand := WsGrand.Add(WsTotal)
	truncatedGrand := rawGrand.Truncate(2)
	WsGrand = storeGrand(truncatedGrand)
	READPARA()
}

func SHOWPARA() {
	WsQtyEd = fmtQtyEd(OrdRec.OrQty)
	WsPriceEd = fmtPriceEd(OrdRec.OrPrice)
	WsTotalEd = fmtTotalEd(WsTotal)
	fmt.Printf("%s %s %s %s %s\n", OrdRec.OrId, OrdRec.OrStat, WsQtyEd, WsPriceEd, WsTotalEd)
}

func SUMMARYPARA() {
	WsGrandEd = fmtGrandEd(WsGrand)
	fmt.Printf("NEW: %s SHIPPED: %s CANCELLED: %s\n", fmt99(WsNewCount), fmt99(WsShipCount), fmt99(WsCancelCount))
	fmt.Printf("INVALID: %s BAD QTY: %s\n", fmt99(WsInvalid), fmt99(WsBadQty))
	fmt.Printf("GRAND TOTAL: %s\n", WsGrandEd)
}

func main() {
	MAINPARA()
}
